def find_solid_rectangles(grid):
    """Find all solid rectangles of same color"""
    h, w = len(grid), len(grid[0])
    rects = []

    # For each top-left corner, find max rectangle
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            # Try expanding rectangle starting at (r,c) with color
            max_h = 1
            while r + max_h < h:
                row_ok = True
                for cc in range(c, c + max_h):
                    if cc >= w or grid[r+max_h][cc] != color:
                        row_ok = False
                        break
                if not row_ok:
                    break
                max_h += 1

            for height in range(max_h, 1, -1):  # Only consider non-trivial rectangles
                width = c + height - c  # At least as wide as tall
                if r + height >= h or c + width >= w:
                    continue
                rect_valid = True
                for ii in range(r, r + height):
                    for jj in range(c, c + width):
                        if grid[ii][jj] != color:
                            rect_valid = False
                            break
                    if not rect_valid:
                        break
                if rect_valid:
                    area = height * width
                    if (height, width) not in [(rh, rw) for rh, rw, _ in rects]:
                        # Check if this area is new
                        rects.append((height, width, area, color, (r, c)))

    # Actually let's do a cleaner sweep
    rects_clean = set()
    best_for_color = {}

    for start_r in range(h):
        for start_c in range(w):
            color = grid[start_r][start_c]
            # Grow rectangle
            for height in range(1, h - start_r + 1):
                valid_row_start = True
                for width_try in range(1, w - start_c + 1):
                    rect_valid = True
                    for rr in range(start_r, start_r + height):
                        for cc in range(start_c, start_c + width_try):
                            if grid[rr][cc] != color:
                                rect_valid = False
                                break
                        if not rect_valid:
                            break
                    if not rect_valid:
                        break

                if rect_valid:
                    key = (height, width_try, color)
                    rects_clean.add(key)

                    # Track largest for each color
                    if key not in best_for_color or area := (height * width_try) > best_for_color[key]['area']:
                        best_for_color[key] = {'area': height * width_try, 'rect': (start_r, start_c, height, width_try)}

    return sorted(rects_clean, key=lambda k: (k[0]*k[1], k[0]+k[1]), reverse=True)[:20]

